#!/usr/bin/env python3
"""Registry coverage report: per state / province / country, the usable layers grouped by park type and use, with their status.
  python3 registry/report.py > registry/COVERAGE.md"""
import collections, json, pathlib, sys
HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent))
from core.registry import Registry, USABLE   # noqa: E402

R = Registry()
by = collections.defaultdict(lambda: collections.defaultdict(list))
for s in R.sources:
    for a in (s.get('areas') or [s.get('area') or s.get('cc')]):
        by[a][(s.get('use', 'outline'), s.get('ptype') or s.get('designation') or '?')].append((R.status(s) or 'unchecked', s.get('grade', 'official')))
print('# Registry coverage (generated by registry/report.py)\n')
print('Status: approved = chat 11 YES rows; club = club-approved lists; verified = live-checked by verify.py; answers = live, no test match;'
      ' blocked / error = not used.\n')
for grp, pref in (('United States', 'US'), ('Canada', 'CA'), ('World', '')):
    HUNT = 'GB DE RO AU BB NL SI CU ES IE FR DK AT LC CH BE MX'.split()
    if pref: areas = sorted(a for a in by if a == pref or a.startswith(pref + '-'))
    else: areas = HUNT + sorted(a for a in by if a and a[:2] not in ('US', 'CA') and a not in HUNT)   # hunt order first
    print(f'## {grp}\n\n| area | outline layers (usable) | by park type | parking | camping | trail | not usable |\n|---|---|---|---|---|---|---|')
    for a in areas:
        d = by.get(a, {})
        use = lambda u: sum(1 for (uu, _), v in d.items() if uu == u for st, g in v if st in USABLE or st == 'unchecked')   # noqa: E731
        types = collections.Counter()
        for (u, t), v in d.items():
            if u == 'outline': types[t] += sum(1 for st, g in v if st in USABLE or st == 'unchecked')
        bad = sum(1 for v in d.values() for st, g in v if st in ('blocked', 'error'))
        approx = sum(1 for v in d.values() for st, g in v if g == 'approximate')
        print(f"| {a} | {use('outline')}{' (' + str(approx) + ' approx)' if approx else ''} | {', '.join(f'{t} {n}' for t, n in types.most_common() if n)} | {use('parking')} | {use('camping')} | {use('trail')} | {bad} |")
    print()
